import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel 6353c49:
# packet.SetLastHurtBy{EntityType: 2969}
V1001 = bytes.fromhex("b22e")

# generated by gophertunnel b8bd735:
# packet.SetLastHurtBy{EntityType: 921}
V2168 = bytes.fromhex("b20e")

GOLDENS = [
    pytest.param(v1001.SetLastHurtByPacket(last_hurt_by=v1001.ActorType.SULFUR_CUBE), V1001, id="v1001"),
    pytest.param(v2168.SetLastHurtByPacket(last_hurt_by=v2168.ActorType.SULFUR_CUBE), V2168, id="v2168"),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_set_last_hurt_by_is_packet_96(version):
    assert version.PACKETS[96] is version.SetLastHurtByPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_last_hurt_by_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_last_hurt_by_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    ("member", "value"),
    [
        pytest.param(v1001.ActorType.SULFUR_CUBE, 2969, id="v1001-sulfur-cube"),
        pytest.param(v2168.ActorType.SULFUR_CUBE, 921, id="v2168-sulfur-cube"),
        pytest.param(v1001.ActorType.MONSTER, 2969 - 153, id="v1001-monster"),
        pytest.param(v2168.ActorType.PATHFINDER_MOB, 921 - 153, id="v2168-pathfinder-mob"),
    ],
)
def test_2168_moves_the_sulfur_cube_from_monster_to_pathfinder_mob_at_index_153(member, value):
    assert member == value


def test_cushion_is_154_at_2168():
    assert v2168.ActorType.CUSHION == 154


def test_1001_has_no_cushion():
    assert not hasattr(v1001.ActorType, "CUSHION")


def test_a_1001_sulfur_cube_does_not_read_as_one_at_2168():
    assert v2168.SetLastHurtByPacket.from_bytes(V1001) != v2168.SetLastHurtByPacket(
        last_hurt_by=v2168.ActorType.SULFUR_CUBE
    )
